update perks set damage = case damage when '(3+Warlock Level)d6' then '(3 + Warlock level)d6 |cs| (3 + úroveň Čaroděje)k6' when '1d6 + Druid level' then '1d6 + Druid level |cs| 1k6 + úroveň Druida' when 'Witcher Level × d6' then 'Witcher level × d6 |cs| úroveň Vědmáka × k6' end where damage in ('(3+Warlock Level)d6','1d6 + Druid level','Witcher Level × d6');
update backgrounds set equipment = replace(equipment::text, '"note": "Silvered"', '"note": "Silvered |cs| Postříbřeno"')::jsonb where equipment::text like '%"note": "Silvered"%';
update character_items set note = 'Silvered |cs| Postříbřeno' where note = 'Silvered';
